mapper.select:
SELECT * FROM stock_watch_analysis_task
WHERE symbol = #{symbol} AND market = #{market}
  AND COALESCE(period_type, 'DAY') = #{periodType}
  AND observation_key = #{observationKey}
ORDER BY id ASC

SELECT * FROM stock_watch_analysis_task
WHERE purpose IN ('stock-analysis-response-v5', 'stock-analysis-response-v6')
  AND status IN ('RESERVED', 'SUBMITTED', 'UNKNOWN', 'RESPONSE_RECEIVED', 'PROJECTION_FAILED')
  AND gmt_modify <= #{before}
ORDER BY gmt_modify ASC, id ASC
LIMIT #{limit}
